package com.shopsphere.controller;
import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.security.CurrentUser; import com.shopsphere.service.AuthService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService service; private final CurrentUser current; public AuthController(AuthService s,CurrentUser c){service=s;current=c;} @PostMapping("/register") public UserResponse register(@Valid @RequestBody RegisterRequest r){return service.register(r);} @PostMapping("/login") public TokenResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @GetMapping("/me") public UserResponse me(Authentication a){var u=current.get(a);return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getRole().name());} }
